import MenuCard from "./MenuCard";

export default function MenuGrid({ addToCart }) {
  const menuItems = [
    { id: 1, name: "Pizza", price: 199 },
    { id: 2, name: "Burger", price: 99 },
    { id: 3, name: "Sandwich", price: 79 },
    { id: 4, name: "Coffee", price: 59 },
    { id: 5, name: "Juice", price: 69 },
  ];

  return (
    <div className="menu-grid">
      {menuItems.map((item) => (
        <MenuCard
          key={item.id}
          item={item}
          addToCart={addToCart}
        />
      ))}
    </div>
  );
}
